INSERT INTO "resource_categories" ("slug","title","description","icon","sort_order") VALUES
('meal-planning','Meal Planning','Weekly plans, balanced plates and prep shortcuts.','calendar',1),
('grocery-shopping','Grocery Shopping','Lists, store walkthroughs and budget-friendly swaps.','cart',2),
('nutrition-reference','Nutrition Reference','Macros, micronutrients, portions and food groups.','book',3),
('mindful-eating','Mindful Eating','Hunger cues, pacing and a calmer relationship with food.','heart',4),
('habits-worksheets','Habits & Worksheets','Printable worksheets and checklists you can actually finish.','shield',5)
INSERT INTO "worksheets" ("slug","title","category","description","intro","instructions","fields") VALUES
('hunger-fullness-log','Hunger & Fullness Log','Mindful Eating','Track how hunger and fullness feel through the day.','Noticing the signals your body sends is the first step toward eating with ease. This log helps you build that awareness without judgment.','Rate before and after each meal on the 1-10 scale: 1 = ravenous, 5 = comfortable, 10 = overly full. Write one word about how you felt.','[{"key":"day","label":"Which day are you logging?","type":"select","options":["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]},{"key":"breakfastBefore","label":"Breakfast - hunger before (1-10)","type":"number","placeholder":"e.g. 4"},{"key":"breakfastAfter","label":"Breakfast - fullness after (1-10)","type":"number","placeholder":"e.g. 6"},{"key":"lunchBefore","label":"Lunch - hunger before (1-10)","type":"number","placeholder":"e.g. 5"},{"key":"lunchAfter","label":"Lunch - fullness after (1-10)","type":"number","placeholder":"e.g. 7"},{"key":"dinnerBefore","label":"Dinner - hunger before (1-10)","type":"number","placeholder":"e.g. 4"},{"key":"dinnerAfter","label":"Dinner - fullness after (1-10)","type":"number","placeholder":"e.g. 6"},{"key":"notes","label":"What did you notice today?","type":"textarea","placeholder":"Patterns, emotions, energy levels..."}]'),
('weekly-checkin','Weekly Check-In','Habits & Worksheets','A five-minute review of your week.','A quick weekly review keeps you honest with yourself and shows progress you might otherwise miss.','Answer honestly - there are no wrong answers. Keep it to five minutes.','[{"key":"wins","label":"Wins from this week","type":"textarea","placeholder":"Meals you enjoyed, movements you did, better sleep..."},{"key":"challenges","label":"What was challenging?","type":"textarea","placeholder":"Busy days, cravings, skipped meals..."},{"key":"energy","label":"Average energy level (1-10)","type":"number","placeholder":"e.g. 6"},{"key":"nextWeekFocus","label":"One focus for next week","type":"text","placeholder":"e.g. pack lunch twice a week"}]'),
('food-mood-journal','Food & Mood Journal','Mindful Eating','Explore how food and mood influence each other.','Mood affects hunger, and food affects mood. Journaling breaks the automatic loop and gives you data about your own patterns.','Note what you ate, how you felt before, and how you felt an hour after. Do this for one or two days.','[{"key":"mealOne","label":"Meal 1 - what you ate","type":"textarea","placeholder":"Be specific but kind - this is data, not a test"},{"key":"moodBeforeOne","label":"Meal 1 - mood before","type":"text","placeholder":"e.g. stressed, tired, happy"},{"key":"moodAfterOne","label":"Meal 1 - mood 1 hour later","type":"text","placeholder":"e.g. calmer, sluggish, same"},{"key":"mealTwo","label":"Meal 2 - what you ate","type":"textarea","placeholder":""},{"key":"moodBeforeTwo","label":"Meal 2 - mood before","type":"text","placeholder":""},{"key":"moodAfterTwo","label":"Meal 2 - mood 1 hour later","type":"text","placeholder":""}]'),
('plate-builder','Build a Balanced Plate','Meal Planning','Plan three days of meals in one sitting.','Planning ahead removes the hardest decision from your busiest moment. Fill this in once and stick it on the fridge.','For each meal pick one protein, one grain or starch, one vegetable and one healthy fat. Simple is better.','[{"key":"monBreakfast","label":"Monday breakfast","type":"text","placeholder":"e.g. oats + Greek yogurt + berries"},{"key":"monLunch","label":"Monday lunch","type":"text","placeholder":""},{"key":"monDinner","label":"Monday dinner","type":"text","placeholder":""},{"key":"tueBreakfast","label":"Tuesday breakfast","type":"text","placeholder":""},{"key":"tueLunch","label":"Tuesday lunch","type":"text","placeholder":""},{"key":"tueDinner","label":"Tuesday dinner","type":"text","placeholder":""},{"key":"wedBreakfast","label":"Wednesday breakfast","type":"text","placeholder":""},{"key":"wedLunch","label":"Wednesday lunch","type":"text","placeholder":""},{"key":"wedDinner","label":"Wednesday dinner","type":"text","placeholder":""}]')
INSERT INTO "checklists" ("slug","title","category","description","items") VALUES
('weekly-grocery-basics','Weekly Grocery Staples','Grocery Shopping','The backbone list most balanced weekly shops build around.','[{"key":"produce-veg","label":"2-3 fresh vegetables"},{"key":"produce-fruit","label":"2-3 pieces of fruit"},{"key":"protein","label":"2 protein sources (eggs, poultry, beans, tofu, fish)"},{"key":"grains","label":"1-2 whole grains (rice, oats, bread, pasta)"},{"key":"dairy","label":"1 dairy or fortified alternative"},{"key":"fats","label":"1 healthy fat (nuts, seeds, olive oil, avocado)"},{"key":"pantry","label":"Pantry check: oil, spices, canned beans"},{"key":"freezer","label":"Freezer backup meal for busy nights"}]'),
('eating-out-smart','Eating Out Without Stress','Mindful Eating','Small choices that make restaurant meals easier.','[{"key":"preview","label":"Look at the menu before arriving"},{"key":"protein-first","label":"Pick a meal with a protein you enjoy"},{"key":"water","label":"Order water with the meal"},{"key":"pace","label":"Eat slowly - give it 20 minutes before deciding on more"},{"key":"sides","label":"Swap one starch side for a vegetable if offered"},{"key":"no-restrict","label":"No "second helping guilt" - enjoy it and move on"}]'),
('new-member-setup','Getting Started With True Diet','Habits & Worksheets','Set up once, then just show up.','[{"key":"profile","label":"Complete your nutrition profile"},{"key":"log-once","label":"Log one meal in the Track tab"},{"key":"hunger","label":"Do one hunger & fullness check-in"},{"key":"read","label":"Read one article in Learn"},{"key":"plan","label":"Try the weekly meal planner once"},{"key":"grocery","label":"Build your first grocery list"},{"key":"notifications","label":"Turn on gentle reminders if you want them"}]'),
('pantry-refresh','Sunday Pantry Refresh','Grocery Shopping','Ten minutes that make the whole week easier.','[{"key":"toss","label":"Toss anything expired from the front shelves"},{"key":"reorg","label":"Move "eat first" items to eye level"},{"key":"prep","label":"Wash and chop one vegetable for the week"},{"key":"protein","label":"Cook one batch protein (eggs, beans, chicken)"},{"key":"stock","label":"Check stock: oil, salt, spices, grains"},{"key":"label","label":"Take a photo of the fridge - future-you will thank you"}]')
INSERT INTO "resource_templates" ("slug","title","category","description","fields") VALUES
('weekly-meal-grid','Weekly Meal Plan Grid','Meal Planning','A blank 7-day grid to fill in however you like.','Day by day, meal by meal. Leave blanks - an 80% filled plan beats a perfect one you abandon.','[{"key":"structure","label":"Layout","type":"static","value":"7 days x 4 meals (breakfast, lunch, dinner, snack)"},{"key":"tip1","label":"Tip","type":"static","value":"Start with breakfasts - they are the easiest wins"},{"key":"tip2","label":"Tip","type":"static","value":"Repeat meals freely; variety is optional, routine is useful"},{"key":"action","label":"Use in app","type":"action","value":"meal-planner"}]'),
('grocery-by-aisle','Grocery List by Aisle','Grocery Shopping','Shop the perimeter first, then the two middle aisles you need.','Grouped by store section so you walk the shop once.','[{"key":"structure","label":"Layout","type":"static","value":"Sections: Produce, Bakery, Dairy, Protein, Pantry, Frozen"},{"key":"tip1","label":"Tip","type":"static","value":"Write quantities before you go - lists grow in the store"},{"key":"action","label":"Use in app","type":"action","value":"grocery-list"}]'),
('balanced-plate','Balanced Plate Template','Nutrition Reference','The visual formula: half plate veg, quarter protein, quarter starch.','Use it for any meal, any cuisine. The proportions matter more than the exact foods.','[{"key":"structure","label":"Layout","type":"static","value":"1/2 vegetables and fruit, 1/4 protein, 1/4 grains or starch, plus a thumb of healthy fat"},{"key":"tip1","label":"Tip","type":"static","value":"Frozen vegetables count. Canned beans count. Relaxed rules last."},{"key":"action","label":"Read more","type":"action","value":"reference-plate"}]'),
('habit-tracker','Mini Habit Tracker','Habits & Worksheets','Track one or two habits for two weeks.','Pick habits so small you can do them on your worst day. Check them off, review on Sunday.','[{"key":"structure","label":"Layout","type":"static","value":"2 habit rows x 14 day columns"},{"key":"tip1","label":"Tip","type":"static","value":"Never miss twice - one gap is life, two gaps start a slide"},{"key":"tip2","label":"Tip","type":"static","value":"Attach the new habit to an existing routine (after coffee, log lunch)"}]')
